-- KRIM Global Corridor Compliance Engine
-- Evidence-first dossier workflow. No corridor is auto-approved.
create table if not exists public.krim_corridor_compliance_dossiers (
 id bigint generated by default as identity primary key,
 corridor_id bigint not null unique references public.krim_network_corridors(id) on delete restrict,
 dossier_status text not null default 'draft' check (dossier_status in ('draft','research_pending','legal_review_pending','approved_for_activation','suspended','retired')),
 transport_mode_codes text[] not null default '{}',
 cargo_scope text[] not null default '{}',
 owner_user_id uuid, approved_by uuid, approved_at timestamptz, next_review_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.krim_corridor_compliance_legs (
 id bigint generated by default as identity primary key,
 dossier_id bigint not null references public.krim_corridor_compliance_dossiers(id) on delete restrict,
 sequence_number integer not null check(sequence_number>0),
 country_id bigint not null references public.krim_countries(id) on delete restrict,
 leg_role text not null check(leg_role in ('origin','transit','destination')),
 border_crossing_label text, transport_mode_codes text[] not null default '{}',
 created_at timestamptz not null default now(), unique(dossier_id,sequence_number)
);
create table if not exists public.krim_corridor_compliance_controls (
 id bigint generated by default as identity primary key,
 dossier_id bigint not null references public.krim_corridor_compliance_dossiers(id) on delete restrict,
 leg_id bigint not null references public.krim_corridor_compliance_legs(id) on delete restrict,
 control_code text not null,
 domain text not null check(domain in ('entity_licensing','transport_permits','customs_trade','cargo_admissibility','sanctions_export_controls','tax_payments','insurance_liability','data_privacy','workforce_safety','environment','border_transit','local_operations')),
 title text not null, mandatory boolean not null default true,
 applicability text not null default 'unknown' check(applicability in ('unknown','yes','no','conditional')),
 review_status text not null default 'pending' check(review_status in ('pending','source_checked','legal_review_pending','approved','rejected','expired')),
 source_id bigint references public.krim_market_regulatory_sources(id) on delete restrict,
 evidence_reference text, reviewer_note text, reviewed_by uuid, reviewed_at timestamptz, expires_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(leg_id,control_code)
);
create table if not exists public.krim_corridor_compliance_events (
 id bigint generated by default as identity primary key,
 dossier_id bigint not null references public.krim_corridor_compliance_dossiers(id) on delete restrict,
 control_id bigint references public.krim_corridor_compliance_controls(id) on delete restrict,
 event_type text not null, actor_user_id uuid, event_data jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now()
);
create index if not exists krim_corridor_legs_dossier_idx on public.krim_corridor_compliance_legs(dossier_id,sequence_number);
create index if not exists krim_corridor_controls_dossier_idx on public.krim_corridor_compliance_controls(dossier_id,review_status);
create index if not exists krim_corridor_controls_leg_idx on public.krim_corridor_compliance_controls(leg_id);
create index if not exists krim_corridor_events_dossier_idx on public.krim_corridor_compliance_events(dossier_id,created_at desc);
alter table public.krim_corridor_compliance_dossiers enable row level security;
alter table public.krim_corridor_compliance_dossiers force row level security;
alter table public.krim_corridor_compliance_legs enable row level security;
alter table public.krim_corridor_compliance_legs force row level security;
alter table public.krim_corridor_compliance_controls enable row level security;
alter table public.krim_corridor_compliance_controls force row level security;
alter table public.krim_corridor_compliance_events enable row level security;
alter table public.krim_corridor_compliance_events force row level security;
revoke all on public.krim_corridor_compliance_dossiers,public.krim_corridor_compliance_legs,public.krim_corridor_compliance_controls,public.krim_corridor_compliance_events from anon,authenticated;
revoke all on sequence public.krim_corridor_compliance_dossiers_id_seq,public.krim_corridor_compliance_legs_id_seq,public.krim_corridor_compliance_controls_id_seq,public.krim_corridor_compliance_events_id_seq from anon,authenticated;

create or replace function public.krim_admin_create_corridor_dossier(p_corridor_id bigint,p_transit_jurisdictions text[] default '{}',p_transport_mode_codes text[] default '{}',p_cargo_scope text[] default '{}')
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_corr public.krim_network_corridors%rowtype; v_id bigint; v_codes text[]; v_code text; v_country_id bigint; v_seq int:=0; v_role text; v_leg bigint; v_control record;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 select * into v_corr from public.krim_network_corridors where id=p_corridor_id;
 if not found then raise exception using errcode='P0002',message='Corridor catalogue record not found'; end if;
 if exists(select 1 from public.krim_corridor_compliance_dossiers where corridor_id=p_corridor_id) then raise exception using errcode='23505',message='Compliance dossier already exists for this corridor'; end if;
 if v_corr.origin_country_id is null or v_corr.destination_country_id is null then raise exception using errcode='22023',message='Origin and destination countries must be defined on the corridor first'; end if;
 if cardinality(coalesce(p_transport_mode_codes,'{}'))=0 then raise exception using errcode='22023',message='At least one transport mode must be specified'; end if;
 if exists(select 1 from unnest(p_transport_mode_codes) x where not exists(select 1 from public.krim_transport_modes m where upper(m.code)=upper(x) and m.is_active)) then raise exception using errcode='22023',message='Unknown or inactive transport mode'; end if;
 insert into public.krim_corridor_compliance_dossiers(corridor_id,transport_mode_codes,cargo_scope,owner_user_id,dossier_status)
 values(p_corridor_id,p_transport_mode_codes,coalesce(p_cargo_scope,'{}'),v_user,'research_pending') returning id into v_id;
 v_codes:=array[(select upper(code) from public.krim_countries where id=v_corr.origin_country_id)] || coalesce(p_transit_jurisdictions,'{}') || array[(select upper(code) from public.krim_countries where id=v_corr.destination_country_id)];
 foreach v_code in array v_codes loop
  v_seq:=v_seq+1;
  select id into v_country_id from public.krim_countries where upper(code)=upper(v_code) and is_active;
  if v_country_id is null then raise exception using errcode='22023',message='Transit jurisdiction is unknown or inactive: '||v_code; end if;
  v_role:=case when v_seq=1 then 'origin' when v_seq=array_length(v_codes,1) then 'destination' else 'transit' end;
  insert into public.krim_corridor_compliance_legs(dossier_id,sequence_number,country_id,leg_role,transport_mode_codes)
  values(v_id,v_seq,v_country_id,v_role,p_transport_mode_codes) returning id into v_leg;
  for v_control in select * from (values
   ('entity_licensing','entity_licensing','Entity presence and legal eligibility'),
   ('transport_permits','transport_permits','Transport operator and mode permits'),
   ('customs_trade','customs_trade','Customs declarations and trade procedures'),
   ('cargo_admissibility','cargo_admissibility','Cargo admissibility, restrictions and licences'),
   ('sanctions_export_controls','sanctions_export_controls','Sanctions, denied parties and export controls'),
   ('tax_payments','tax_payments','Tax, invoicing, payments and foreign exchange'),
   ('insurance_liability','insurance_liability','Insurance, liability and claims'),
   ('data_privacy','data_privacy','Privacy, data localisation and cross-border transfers'),
   ('workforce_safety','workforce_safety','Workforce, driver and safety obligations'),
   ('environment','environment','Environmental and facility requirements'),
   ('border_transit','border_transit','Border, transit and customs-crossing permissions'),
   ('local_operations','local_operations','Local operating partners and emergency support')
  ) as x(code,domain,title)
  loop
   insert into public.krim_corridor_compliance_controls(dossier_id,leg_id,control_code,domain,title)
   values(v_id,v_leg,v_control.code,v_control.domain,v_control.title);
  end loop;
 end loop;
 insert into public.krim_corridor_compliance_events(dossier_id,event_type,actor_user_id,event_data)
 values(v_id,'dossier_created',v_user,jsonb_build_object('corridor_id',p_corridor_id,'jurisdictions',v_codes,'transport_modes',p_transport_mode_codes));
 return jsonb_build_object('dossier_id',v_id,'jurisdictions',v_codes,'status','research_pending');
end $$;

create or replace function public.krim_admin_list_corridor_dossiers()
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_data jsonb;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('dossier_id',d.id,'corridor_id',c.id,'corridor_code',c.corridor_code,'corridor_name',c.corridor_name,'status',d.dossier_status,'transport_modes',d.transport_mode_codes,'jurisdictions',coalesce((select jsonb_agg(jsonb_build_object('code',co.code,'name',co.name,'role',l.leg_role,'sequence',l.sequence_number) order by l.sequence_number) from public.krim_corridor_compliance_legs l join public.krim_countries co on co.id=l.country_id where l.dossier_id=d.id),'[]'::jsonb),'controls_total',(select count(*) from public.krim_corridor_compliance_controls x where x.dossier_id=d.id),'controls_approved',(select count(*) from public.krim_corridor_compliance_controls x where x.dossier_id=d.id and x.review_status='approved' and x.applicability in ('yes','no','conditional') and x.source_id is not null and nullif(btrim(x.evidence_reference),'') is not null and nullif(btrim(x.reviewer_note),'') is not null and (x.expires_at is null or x.expires_at>now())),'next_review_at',d.next_review_at) order by c.corridor_name),'[]'::jsonb) into v_data from public.krim_corridor_compliance_dossiers d join public.krim_network_corridors c on c.id=d.corridor_id;
 return jsonb_build_object('dossiers',v_data);
end $$;

create or replace function public.krim_admin_get_corridor_dossier(p_dossier_id bigint)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_data jsonb;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 select jsonb_build_object('dossier',to_jsonb(d),'corridor',to_jsonb(c),'legs',coalesce((select jsonb_agg(jsonb_build_object('leg',to_jsonb(l),'country_code',co.code,'country_name',co.name,'controls',(select coalesce(jsonb_agg(jsonb_build_object('control_id',x.id,'control_code',x.control_code,'domain',x.domain,'title',x.title,'mandatory',x.mandatory,'applicability',x.applicability,'review_status',x.review_status,'source_id',x.source_id,'evidence_reference',x.evidence_reference,'reviewer_note',x.reviewer_note,'expires_at',x.expires_at)),'[]'::jsonb) from public.krim_corridor_compliance_controls x where x.leg_id=l.id)) order by l.sequence_number) from public.krim_corridor_compliance_legs l join public.krim_countries co on co.id=l.country_id where l.dossier_id=d.id),'[]'::jsonb)) into v_data from public.krim_corridor_compliance_dossiers d join public.krim_network_corridors c on c.id=d.corridor_id where d.id=p_dossier_id;
 if v_data is null then raise exception using errcode='P0002',message='Corridor dossier not found'; end if;
 return v_data;
end $$;

create or replace function public.krim_admin_review_corridor_control(p_control_id bigint,p_applicability text,p_review_status text,p_source_id bigint,p_evidence_reference text,p_reviewer_note text,p_expires_at timestamptz default null)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_control public.krim_corridor_compliance_controls%rowtype; v_jurisdiction text; v_source public.krim_market_regulatory_sources%rowtype;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 if p_applicability not in ('yes','no','conditional') or p_review_status not in ('source_checked','legal_review_pending','approved','rejected') then raise exception using errcode='22023',message='Invalid review decision'; end if;
 select x.* into v_control from public.krim_corridor_compliance_controls x where x.id=p_control_id for update;
 if not found then raise exception using errcode='P0002',message='Corridor control not found'; end if;
 select upper(c.code) into v_jurisdiction from public.krim_corridor_compliance_legs l join public.krim_countries c on c.id=l.country_id where l.id=v_control.leg_id;
 if p_review_status in ('source_checked','approved') then
  if p_source_id is null or nullif(btrim(p_evidence_reference),'') is null or nullif(btrim(p_reviewer_note),'') is null then raise exception using errcode='22023',message='Reviewed source, evidence reference and reviewer rationale are mandatory'; end if;
  select * into v_source from public.krim_market_regulatory_sources where id=p_source_id;
  if not found or v_source.jurisdiction_code not in (v_jurisdiction,'*') or v_source.review_status not in ('source_checked','legal_reviewed') or (v_source.effective_until is not null and v_source.effective_until<current_date) then raise exception using errcode='22023',message='Source must be reviewed, current and applicable to this jurisdiction'; end if;
  if v_control.domain in ('entity_licensing','transport_permits','customs_trade','cargo_admissibility','sanctions_export_controls','tax_payments','border_transit') and p_review_status='approved' and (v_source.source_kind not in ('qualified_legal_opinion','qualified_tax_opinion') or v_source.review_status<>'legal_reviewed') then raise exception using errcode='22023',message='This legal or tax control requires a qualified, legally reviewed opinion'; end if;
 end if;
 update public.krim_corridor_compliance_controls set applicability=p_applicability,review_status=p_review_status,source_id=p_source_id,evidence_reference=nullif(btrim(p_evidence_reference),''),reviewer_note=nullif(btrim(p_reviewer_note),''),reviewed_by=v_user,reviewed_at=now(),expires_at=p_expires_at,updated_at=now() where id=p_control_id;
 insert into public.krim_corridor_compliance_events(dossier_id,control_id,event_type,actor_user_id,event_data)
 values(v_control.dossier_id,p_control_id,'control_reviewed',v_user,jsonb_build_object('applicability',p_applicability,'review_status',p_review_status,'source_id',p_source_id,'expires_at',p_expires_at));
 return jsonb_build_object('control_id',p_control_id,'review_status',p_review_status,'jurisdiction',v_jurisdiction);
end $$;

create or replace function public.krim_admin_set_corridor_dossier_status(p_dossier_id bigint,p_status text,p_reviewer_note text default null,p_next_review_at timestamptz default null)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_d public.krim_corridor_compliance_dossiers%rowtype; v_total int; v_approved int; v_bad_packs int;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 if p_status not in ('research_pending','legal_review_pending','approved_for_activation','suspended','retired') then raise exception using errcode='22023',message='Invalid corridor dossier status'; end if;
 select * into v_d from public.krim_corridor_compliance_dossiers where id=p_dossier_id for update;
 if not found then raise exception using errcode='P0002',message='Corridor dossier not found'; end if;
 if p_status='approved_for_activation' then
  select count(*),count(*) filter(where c.review_status='approved' and c.applicability in ('yes','no','conditional') and c.source_id is not null and nullif(btrim(c.evidence_reference),'') is not null and nullif(btrim(c.reviewer_note),'') is not null and (c.expires_at is null or c.expires_at>now())) into v_total,v_approved from public.krim_corridor_compliance_controls c where c.dossier_id=p_dossier_id and c.mandatory;
  select count(*) into v_bad_packs from public.krim_corridor_compliance_legs l join public.krim_countries co on co.id=l.country_id left join public.krim_country_operating_packs p on p.jurisdiction_code=upper(co.code) where l.dossier_id=p_dossier_id and (p.id is null or p.pack_status<>'approved' or exists(select 1 from public.krim_country_pack_controls pc where pc.pack_id=p.id and pc.mandatory and (pc.review_status<>'approved' or pc.applicability not in ('yes','no','conditional') or pc.source_id is null or nullif(btrim(pc.evidence_reference),'') is null or nullif(btrim(pc.reviewer_note),'') is null or (pc.expires_at is not null and pc.expires_at<=now()))));
  if v_total=0 or v_total<>v_approved or v_bad_packs>0 or nullif(btrim(p_reviewer_note),'') is null then raise exception using errcode='23514',message='Activation blocked: every mandatory corridor control and every jurisdiction country pack must be approved, evidenced, sourced and current; reviewer rationale is required'; end if;
 end if;
 update public.krim_corridor_compliance_dossiers set dossier_status=p_status,approved_by=case when p_status='approved_for_activation' then v_user else null end,approved_at=case when p_status='approved_for_activation' then now() else null end,next_review_at=p_next_review_at,updated_at=now() where id=p_dossier_id;
 insert into public.krim_corridor_compliance_events(dossier_id,event_type,actor_user_id,event_data) values(p_dossier_id,'dossier_status_changed',v_user,jsonb_build_object('status',p_status,'reviewer_note',p_reviewer_note,'next_review_at',p_next_review_at));
 return jsonb_build_object('dossier_id',p_dossier_id,'status',p_status,'controls_total',v_total,'controls_approved',v_approved,'jurisdictions_without_approved_country_pack',v_bad_packs);
end $$;

create or replace function public.krim_admin_list_corridor_catalogue()
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_user uuid:=auth.uid(); v_data jsonb;
begin
 if v_user is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'corridor_code',c.corridor_code,'corridor_name',c.corridor_name,'origin_country_id',c.origin_country_id,'destination_country_id',c.destination_country_id,'status',c.status) order by c.corridor_name),'[]'::jsonb) into v_data from public.krim_network_corridors c;
 return jsonb_build_object('corridors',v_data);
end $$;

revoke all on function public.krim_admin_create_corridor_dossier(bigint,text[],text[],text[]) from public,anon;
revoke all on function public.krim_admin_list_corridor_dossiers() from public,anon;
revoke all on function public.krim_admin_get_corridor_dossier(bigint) from public,anon;
revoke all on function public.krim_admin_review_corridor_control(bigint,text,text,bigint,text,text,timestamptz) from public,anon;
revoke all on function public.krim_admin_set_corridor_dossier_status(bigint,text,text,timestamptz) from public,anon;
revoke all on function public.krim_admin_list_corridor_catalogue() from public,anon;
grant execute on function public.krim_admin_create_corridor_dossier(bigint,text[],text[],text[]) to authenticated;
grant execute on function public.krim_admin_list_corridor_dossiers() to authenticated;
grant execute on function public.krim_admin_get_corridor_dossier(bigint) to authenticated;
grant execute on function public.krim_admin_review_corridor_control(bigint,text,text,bigint,text,text,timestamptz) to authenticated;
grant execute on function public.krim_admin_set_corridor_dossier_status(bigint,text,text,timestamptz) to authenticated;
grant execute on function public.krim_admin_list_corridor_catalogue() to authenticated;
